    /// <summary>
    /// Check if a given media theme has been activated.<br/>
    /// 
    /// @param theme_name The name of the theme.<br/>
    /// @return True if the theme is activated.<br/>
    /// </summary>
    /// <remarks>C++: <c>bool Rml::Context::IsThemeActive(const String&amp; theme_name) const</c></remarks>
    public bool IsThemeActive(string themeName)
    {
        scoped Utf8StringMarshaller.ManagedToUnmanagedIn themeName_m = new();
        themeName_m.FromManaged(themeName, stackalloc byte[Utf8StringMarshaller.ManagedToUnmanagedIn.BufferSize]);
        try
        {
            return NativeMethods.RmlContext_IsThemeActive(Handle, themeName_m.ToUnmanaged()) != 0;
        }
        finally
        {
            themeName_m.Free();
        }
    }

